export default {
  id: "eval-budget-continuation-seed",
  async setup(ctx: any) {
    const seeded = new Set<string>()

    await ctx.session.hook("context", async (event: any) => {
      const sessionID = String(event?.sessionID ?? "").trim()
      if (!sessionID || event?.agent !== "general" || seeded.has(sessionID)) return
      seeded.add(sessionID)

      const workflowId = "eval-budget-continuation"
      const stepId = "worker"
      const now = "2026-09-24T09:00:00.000Z"
      const progress = {
        newEvidence: false,
        changedHypothesis: false,
        changedStrategy: true,
        reducedUnresolved: true,
      }

      await ctx.storage.set(`workflow/${workflowId}`, {
        id: workflowId,
        revision: 0,
        anchor: `task:${workflowId}`,
        request: "Continue the already-started bounded Worker task.",
        createdBySession: sessionID,
        createdAt: now,
        steps: [{
          id: stepId,
          agent: "worker",
          kind: "work",
          dependsOn: [],
          status: "pending",
        }],
      })

      await ctx.storage.set(`session/${sessionID}`, workflowId)
      await ctx.storage.set(`session-step/${sessionID}`, "")
      await ctx.storage.set(`session-oq/${sessionID}`, "")
      await ctx.storage.set(`limits/${workflowId}`, {
        maxTotalDispatches: 40,
        maxDispatchesPerStep: 3,
        maxReviewerDispatchesPerStep: 3,
        maxCriticDispatchesPerStep: 2,
        maxExtraDispatchesPerStep: 3,
        maxProviderRetries: 2,
      })
      await ctx.storage.set(`budget/${workflowId}`, {
        totalDispatches: 6,
        byKey: { "step:worker": 6 },
        seenDispatches: [
          "seed-worker-1",
          "seed-worker-2",
          "seed-worker-3",
          "seed-worker-4",
          "seed-worker-5",
          "seed-worker-6",
        ],
        grants: [1, 2, 3].map((attempt) => ({
          key: "step:worker",
          agent: "worker",
          grantedBy: "general",
          reason: `Seeded material-progress recovery ${attempt}`,
          progress,
          evidence: [],
          grantedAt: `2026-09-24T09:0${attempt}:00.000Z`,
        })),
        exhausted: "extra dispatch grant limit 3 reached for step:worker",
      })
      await ctx.storage.set(`scope/${workflowId}/${stepId}`, {
        workflowId,
        stepId,
        write: ["scratch/**"],
      })
    })
  },
}

